import marshal, importlib.util, sys, py_compile, os, dis
def load(p):
    f=open(p,'rb'); f.read(12); return marshal.load(f)
old = load('dateutil/__pycache__/relativedelta.cpython-36.pyc')
src = open('dateutil/relativedelta.py').read()
new = compile(src, 'dateutil/relativedelta.py', 'exec')
def find(c, name):
    for k in c.co_consts:
        if hasattr(k,'co_name'):
            if k.co_name==name: return k
            r=find(k,name)
            if r: return r
for name in ['_fix','normalized','__add__','__mul__','__sub__','__init__','weeks','__neg__','__eq__','_set_months','__div__','__bool__']:
    a=find(old,name); b=find(new,name)
    if a is None or b is None:
        print(name, 'missing', a, b); continue
    print(name, 'same' if a.co_code==b.co_code and a.co_consts==b.co_consts else 'DIFFERENT')
