cd /dateutil && python - <<'EOF'
import marshal, os, glob, importlib.util, sys
for pyc in glob.glob('dateutil/**/__pycache__/*.pyc', recursive=True):
    src = pyc.split('/__pycache__/')[0] + '/' + os.path.basename(pyc).split('.')[0] + '.py'
    if not os.path.exists(src):
        print('no src', pyc); continue
    f=open(pyc,'rb'); f.read(12)
    try:
        old=marshal.load(f)
    except Exception as e:
        print('err',pyc,e); continue
    new=compile(open(src).read(), src, 'exec')
    def walk(c):
        yield c
        for k in c.co_consts:
            if hasattr(k,'co_code'):
                for x in walk(k): yield x
    o={ (c.co_name, c.co_firstlineno): c for c in walk(old)}
    n={ (c.co_name, c.co_firstlineno): c for c in walk(new)}
    diff=[]
    for k in set(o)|set(n):
        if k not in o or k not in n: diff.append((k,'missing')); continue
        if o[k].co_code!=n[k].co_code or o[k].co_consts!=n[k].co_consts: diff.append((k,'diff'))
    print(pyc, len(diff), diff[:10])
EOF

